package os.aios.agent;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
/** Real model handoff on a harmless Clock screen; never sets alarms or timers. */
public final class HandoffLiveTests extends Instrumentation {
 int checks;Throwable mainError;void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable t){mainError=t;}});if(mainError!=null)throw new RuntimeException(mainError);}
 public void onStart(){Bundle out=new Bundle();String created="";UiViewerActivity viewer=null;
 try{Context c=getTargetContext();check(!java.util.Set.of("running","queued").contains(AssistantConversation.state(c).optString("status")),"previous request idle");AssistantConversation.fresh(c);
  AssistantConversation.enqueue(c,"This is a safe UI handoff acceptance test. Open the Clock app (com.android.deskclock) in a NEW background screen owned by this conversation. Do not change alarms, timers, or any data. Use the native handoff intervention tool to let me interact with that original screen. When I return control, read the screen again and reply HANDOFF_ACCEPTED. Do not save memories or skills. If Clock belongs to another conversation, report that and stop; do not close another conversation's screen.");c.startForegroundService(new Intent(c,AgentService.class));long end=SystemClock.elapsedRealtime()+240000;JSONObject handoff=null;
  while(SystemClock.elapsedRealtime()<end){JSONObject s=AssistantConversation.state(c);AgentService service=AgentService.instance;if(service!=null&&!s.optString("thread_id").isEmpty()){JSONArray rows=service.interventions.store.list(s.getString("thread_id"));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.optString("state").equals("waiting_user")&&row.getJSONObject("arguments").optString("kind").equals("handoff")&&!row.getJSONObject("arguments").optString("ui_session_id").isEmpty()){handoff=row;break;}}}if(handoff!=null)break;if(s.optString("status").equals("failed")||s.optString("status").equals("completed"))throw new AssertionError("No handoff: "+s.optString("reply")+s.optString("error"));Thread.sleep(300);}
  check(handoff!=null,"real model requested user handoff");final JSONObject row=handoff;AgentService service=AgentService.instance;String sid=row.getJSONObject("arguments").getString("ui_session_id");created=sid;check(AssistantConversation.uiOwner(c,sid).optString("thread_id").equals(AssistantConversation.state(c).optString("thread_id")),"test owns screen");
  main(()->{try{for(int i=0;i<8;i++)service.interventions.begin(row.getString("id"),row.getLong("revision"));}catch(Exception e){throw new RuntimeException(e);}});
  viewer=(UiViewerActivity)startActivitySync(new Intent(c,UiViewerActivity.class).putExtra("session_id",sid).putExtra("intervention_id",row.getString("id")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);UiSessionController screen=service.ui.find(sid);check(screen!=null&&screen.mirrorUserControl,"original screen in user control");
  for(int i=0;i<12;i++){screen.noteMirrorInteraction();Thread.sleep(40);}JSONObject latest=service.interventions.store.get(row.getString("id"));check(latest.getLong("revision")==row.getLong("revision")+1,"repeated user activity retains same confirmation revision");
  UiViewerActivity active=viewer;main(()->active.control.performClick());Thread.sleep(600);latest=service.interventions.store.get(row.getString("id"));check(latest.optString("state").equals("resolved")&&latest.getJSONObject("result").optString("selected_option").equals("returned"),"viewer returns original handoff");
  main(()->{try{for(int i=0;i<5;i++)service.interventions.returnHandoff(row.getString("id"),sid);}catch(Exception e){throw new RuntimeException(e);}});
  boolean done=false;while(SystemClock.elapsedRealtime()<end){JSONObject s=AssistantConversation.state(c);if(s.optString("status").equals("completed")){check(s.optString("reply").contains("HANDOFF_ACCEPTED"),"real model resumes and reads back");done=true;out.putString("thread",s.optString("thread_id"));break;}if(s.optString("status").equals("failed"))throw new AssertionError(s.optString("error"));Thread.sleep(300);}check(done,"handoff completes within deadline");out.putString("result","PASS "+checks+" checks");
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));}finally{if(viewer!=null){UiViewerActivity v=viewer;runOnMainSync(v::finish);}if(!created.isEmpty())try{AgentService service=AgentService.instance;if(service!=null)service.ui.call(new JSONObject().put("op","close").put("session_id",created));}catch(Exception ignored){}finish(out.containsKey("error")?0:-1,out);}}
}
